# owner: platform
"""Absence notices that go home to parents."""

from typing import Iterable, List, Set
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date


def format_day(when: date) -> str:
    return f"{when:%B} {when.day}, {when.year}"


def foreign_ids(
    student: Student, found: List[Mark]
) -> Set[str]:
    seen = {mark.student_id for mark in found}
    return seen - {student.student_id}


def own_marks(
    student: Student, marks: Iterable[Mark]
) -> List[Mark]:
    found = list(marks)
    others = foreign_ids(student, found)
    if others:
        raise ValueError(f"foreign ids: {sorted(others)}")
    return found


def notice_text(student: Student, days: List[date]) -> str:
    """Parent-facing text listing the absent dates."""
    name = f"{student.first_name} {student.last_name}"
    unit = "day" if len(days) == 1 else "days"
    count = f"{len(days)} {unit}"
    dates = "; ".join(format_day(when) for when in days)
    notice = f"Attendance notice for {name}."
    return f"{notice} Absent {count}: {dates}."


def build_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    absent = days_missed(own_marks(student, marks))
    days = sorted(set(absent))
    if not days:
        raise ValueError("no absences to report")
    return notice_text(student, days)
